const patient = $('Edit Fields').first().json;

const symptoms = patient.symptoms.toLowerCase().split(" ");

const diseases = $('Load Disease Database').first().json.diseases;

let bestMatch = diseases[0];
let bestScore = 0;

for (const disease of diseases) {

  let score = 0;

  for (const symptom of symptoms) {

    if (disease.symptoms.includes(symptom)) {
      score++;
    }

  }

  if (score > bestScore) {
    bestScore = score;
    bestMatch = disease;
  }

}

return [
  {
    json: {
      Name: patient.Name,
      matchedDisease: bestMatch.name,
      severity: bestMatch.severity,
      treatment: bestMatch.treatment
    }
  }
];

